import{_ as e,o,c as a,a2 as l}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"2012年 · 复利之塔","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2012年.md","filePath":"05_quotes/by-year/2012年.md"}'),r={name:"05_quotes/by-year/2012年.md"};function u(q,t,c,s,h,_){return o(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="_2012年-·-复利之塔" tabindex="-1">2012年 · 复利之塔 <a class="header-anchor" href="#_2012年-·-复利之塔" aria-label="Permalink to &quot;2012年 · 复利之塔&quot;">​</a></h1><blockquote><p>&quot;美国经济的基本游戏对投资者和管理者都极为有利。要有根据地积极进取，而不是被不确定性吓退。&quot;——巴菲特（82岁）</p></blockquote><p>本页收录2012年致股东信中的经典语录。伯克希尔总收益241亿美元，五大业务税前利润首破百亿美元，巴菲特在信中展示了留存收益再投资的复利魔力，并首次透露了身后的资产配置遗嘱。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;无论市场如何，我对伙伴查理·芒格和我都不换衡量标准。我们的工作是推动内在商业价值以比标普500市场涨幅更快的速度增长。做到了这一点，伯克希尔的股价长期来看将超越标普500。&quot;</p></blockquote><blockquote><p>&quot;任何&#39;可怕&#39;的消息而卖出优秀企业通常是一个糟糕的决定。&quot;</p></blockquote><blockquote><p>&quot;保险浮存金就是&#39;免费&#39;资金的使用——而且更好的是，因为持有这些资金而获得报酬。&quot;</p></blockquote><blockquote><p>&quot;GEICO卓越业绩的功劳属于托尼·尼塞利，1993年成为CEO，此后公司一直在腾飞。没有比托尼更好的经理人了。我应该补充：壁虎吉祥物有特别讨人喜欢的品质——他无偿工作。与人类代言人不同，他从未因名气而自我膨胀。&quot;</p></blockquote><blockquote><p>&quot;当你看到他的成就时，我揉揉眼睛。1951年我第一次接触GEICO时，被该公司相对于行业巨头所承受费用的巨大成本优势所震撼。我清楚地看到GEICO会成功，因为它值得成功。&quot;</p></blockquote><blockquote><p>&quot;聪明投资并不复杂，尽管这远不是说它很容易。投资者需要的是正确评估选定企业的能力。请注意&#39;选定&#39;这个词：你不必成为每家公司专家，只需要能够在你的能力范围内评估公司。&quot;</p></blockquote><blockquote><p>&quot;如果你不愿意持有一只股票十年，那连十分钟都不应该持有。&quot;</p></blockquote><blockquote><p>&quot;成功的投资并不需要理解贝塔、有效市场、现代投资组合理论、期权定价或新兴市场知识。&quot;</p></blockquote><blockquote><p>&quot;报纸的核心价值在于：如果你想知道你镇上发生了什么，没有任何东西可以替代一份做好工作的本地报纸。读者眼睛可能在阅读国际新闻后变得呆滞，但关于他自己或邻居的故事会读到最后。&quot;</p></blockquote><blockquote><p>&quot;最大化一家优秀企业的业绩需要管理和专注。我们对激励薪酬的看法：目标应该根据特定经营业务的经济状况量身定制，性质简单，以便可以轻松衡量其实现程度，并与参与者的日常活动直接相关。&quot;</p></blockquote><blockquote><p>&quot;我们持续改善子公司业务，通过补强收购进一步提高其利润，受益于被投资方的增长，当股价以显著低于内在价值折扣时回购，以及偶尔进行大型收购。我们还将通过极少发行股票来最大化您的收益。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2012年伯克希尔每股账面价值增长14.4%，连续第48年超越标普0.5个百分点，但该年度略低于指数表现。伯克希尔年末拥有28.8万名员工，总浮存金达731亿美元，连续第十年实现承保盈利。巴菲特在2012年未完成任何大型收购，但完成26项补强型收购，投入约23亿美元。五大业务（动力五强）税前利润首次突破百亿美元大关。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-2012年-翻译-·-01-letters-2012年-核心总结-·-01-letters-2012年-思维导图" tabindex="-1"><a href="/01_letters/2012年/翻译.html">01_letters/2012年/翻译</a> · <a href="/01_letters/2012年/核心总结.html">01_letters/2012年/核心总结</a> · <a href="/01_letters/2012年/思维导图.html">01_letters/2012年/思维导图</a> <a class="header-anchor" href="#_01-letters-2012年-翻译-·-01-letters-2012年-核心总结-·-01-letters-2012年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/2012年/翻译]] · [[→ 核心总结|01_letters/2012年/核心总结]] · [[→ 思维导图|01_letters/2012年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/2012年/翻译.html">/01_letters/2012年/翻译</a></li></ul>',24)])])}const i=e(r,[["render",u]]);export{p as __pageData,i as default};
